import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./login.css";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  // 🔄 Function to refresh access token
  const refreshAccessToken = async () => {
    const refreshToken = localStorage.getItem("refresh_token");
    if (!refreshToken) return;

    try {
      const response = await fetch("http://127.0.0.1:8000/api/auth/token/refresh/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ refresh: refreshToken }),
      });

      const data = await response.json();
      if (response.ok) {
        localStorage.setItem("token", data.access); // update access token
      } else {
        console.error("Failed to refresh token:", data);
        localStorage.removeItem("token");
        localStorage.removeItem("refresh_token");
        navigate("/login");
      }
    } catch (err) {
      console.error("Refresh token error:", err);
      localStorage.removeItem("token");
      localStorage.removeItem("refresh_token");
      navigate("/login");
    }
  };

  // 🕒 Setup auto-refresh (every 59 mins for a 60-min token)
  useEffect(() => {
    const interval = setInterval(refreshAccessToken, 59 * 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors({});

    if (!email || !password) {
      setErrors({ form: "Email and password are required" });
      return;
    }

    try {
      const response = await fetch("http://127.0.0.1:8000/api/auth/token/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: email, password }),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("token", data.access);
        localStorage.setItem("refresh_token", data.refresh);

        toast.success("🎉 Login successful!", {
          position: "top-right",
          autoClose: 3000,
        });

        setTimeout(() => {
          navigate("/dashboard");
        }, 1000);
      } else {
        console.error("Login error:", data);
        setErrors({ form: data.detail || "Invalid credentials" });
      }
    } catch (err) {
      console.error("Network error:", err);
      setErrors({ form: "Network error, try again later" });
    }
  };

  return (
    <div className="main">
      <ToastContainer />

      <div className="login-container">
        <div className="login-header">
          <h2>Login</h2>
        </div>
        <form onSubmit={handleSubmit} className="login-form" noValidate>
          {errors.form && <p className="error-text">{errors.form}</p>}

          <div className="input-group">
            <label>Username</label>
            <input
              type="text"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="input-group">
            <label>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button type="submit" className="login-button">
            Login
          </button>
        </form>
      </div>
    </div>
  );
}

export default Login;
